#include "../../03-字符串/后缀树Ukkonen.cpp"
int main(){mt19937 g(137);for(int t=0;t<300;t++){string s;for(int n=g()%60;n--;)s+=char('a'+g()%4);SuffixTree a(s);assert(a.nodes<=(int)a.next.size());set<string>suffix;auto dfs=[&](auto&&dfs,int u,string path)->void{if(u)path+=a.text.substr(a.l[u],a.r[u]-a.l[u]);bool leaf=true;for(int c=0;c<27;c++)if(a.next[u][c]>=0)leaf=false,dfs(dfs,a.next[u][c],path);if(leaf)suffix.insert(path);};dfs(dfs,0,"");for(int i=0;i<=(int)s.size();i++)assert(suffix.count(a.text.substr(i)));assert(suffix.size()==s.size()+1);for(int k=0;k<100;k++){string p;for(int n=g()%10;n--;)p+=char('a'+g()%4);assert(a.contains(p)==(s.find(p)!=string::npos));}}SuffixTree a(string(100000,'a'));assert(a.contains(string(100,'a')));}
